// Route incoming MQTT messages
// output 1: bridge/devices / 2: bridge/info / 3: bridge/state / 4: bridge/response
// output 5: device state (topic = friendly name) / 6: device availability (topic = friendly name) / 7: DKNR command

const mqtt = global.get('mqtt', 'default') || {};
const base = typeof mqtt.source === 'string' ? mqtt.source : '';
const topic = typeof mqtt.topic === 'string' ? mqtt.topic : '';
const t = typeof msg.topic === 'string' ? msg.topic : '';

// DKNR command: topic / set / zigbee / id / entity
if (topic !== '' && t.startsWith(topic + '/set/zigbee/')) {

    return [null, null, null, null, null, null, msg];
}

if (base === '' || !t.startsWith(base + '/')) {

    return;
}

const rest = t.slice(base.length + 1);

if (rest.startsWith('bridge/')) {
    switch (rest) {
        case 'bridge/devices':

            return [msg, null, null, null, null, null, null];
        case 'bridge/info':

            return [null, msg, null, null, null, null, null];
        case 'bridge/state':

            return [null, null, msg, null, null, null, null];
    }
    if (rest.startsWith('bridge/response/')) {
        msg.topic = rest.slice('bridge/response/'.length);

        return [null, null, null, msg, null, null, null];
    }

    // logging, definitions, groups, extensions, event...
    return;
}

// commands sent to devices by anybody
if (/\/(set|get)(\/.*)?$/.test(rest)) {

    return;
}

if (rest.endsWith('/availability')) {
    msg.topic = rest.slice(0, -'/availability'.length);

    return [null, null, null, null, null, msg, null];
}

msg.topic = rest;

return [null, null, null, null, msg, null, null];

// Parse Zigbee2MQTT bridge/devices and build DKNR entities from devices exposes
// output 1: one message per device (topic = device id) / output 2: discovery
// output 3: removed devices cleanup (MQTT) / output 4: first state read (MQTT) / output 5: UI refresh

if (!Array.isArray(msg.payload)) {
    node.status({ fill: 'red', shape: 'ring', text: 'liste invalide' });

    return;
}

const describe = global.get('describe', 'memoryOnly') || {};
const Z = describe.zigbee || {};
const mqtt = global.get('mqtt', 'default') || {};
const previous = global.get('devices', 'memoryOnly') || {};
const states = global.get('states', 'memoryOnly') || {};
const source = 'zigbee';

function category(name, access, cat) {
    let c = typeof cat === 'string' ? cat : ((Z.diagnostic || []).includes(name) ? 'diagnostic' : '');
    if (c === 'config' && !(access & 2)) {
        c = '';
    }

    return c;
}

// Build one DKNR entity from a Zigbee2MQTT generic expose
function entity(e) {
    const name = typeof e.name === 'string' ? e.name : '';
    const property = typeof e.property === 'string' && e.property !== '' ? e.property : name;
    const access = typeof e.access === 'number' ? e.access : 1;

    if (property === '' || !(access & 3)) {

        return null;
    }

    let label = (Z.labels || {})[name] || e.label || property;
    if (property !== name) {
        label += ' ' + (e.endpoint || property.slice(name.length + 1) || property);
    }

    let def = {
        'property': property,
        'name': label,
        'access': access,
        'group': access & 2 ? 'command' : 'sensor',
        'unit': '',
        'invert': false,
        'ha_device': '',
        'ha_state': '',
        'ha_category': category(name, access, e.category)
    };

    switch (e.type) {
        case 'binary':
            def.type = 'binary';
            def.value_on = e.value_on;
            def.value_off = e.value_off;
            if (e.value_toggle !== undefined) {
                def.value_toggle = e.value_toggle;
            }
            def.ha_type = access & 2 ? 'switch' : 'binary_sensor';
            if (def.ha_type === 'binary_sensor') {
                def.ha_device = (Z.binary || {})[name] || '';
                def.invert = (Z.inverted || []).includes(name);
            }
            def.display = name === 'state' ? 'state' : (name === 'contact' ? 'contact' : '');
            break;

        case 'numeric':
            def.type = 'number';
            def.unit = typeof e.unit === 'string' ? e.unit : '';
            if (typeof e.value_min === 'number') {
                def.min = e.value_min;
            }
            if (typeof e.value_max === 'number') {
                def.max = e.value_max;
            }
            if (typeof e.value_step === 'number') {
                def.step = e.value_step;
            }
            def.ha_type = access & 2 ? 'number' : 'sensor';
            if (def.ha_type === 'sensor') {
                const byProperty = (Z.property || {})[name];
                if (Array.isArray(byProperty) && byProperty[0] === def.unit) {
                    def.ha_device = byProperty[1];
                } else {
                    def.ha_device = (Z.unit || {})[def.unit] || '';
                }
                if (def.unit !== '' || def.ha_device !== '') {
                    def.ha_state = def.ha_device === 'energy' ? 'total_increasing' : 'measurement';
                }
            }
            break;

        case 'enum':
            if ((Z.text || []).includes(name)) {
                def.type = 'text';
                def.ha_type = 'sensor';
                def.group = 'sensor';
            } else {
                def.type = 'enum';
                def.values = (Array.isArray(e.values) ? e.values : []).map(v => String(v));
                def.ha_type = access & 2 ? 'select' : 'sensor';
                if (def.ha_type === 'sensor' && def.values.length > 0) {
                    def.ha_device = 'enum';
                }
            }
            break;

        case 'text':
            def.type = 'text';
            def.ha_type = access & 2 ? 'text' : 'sensor';
            break;

        default:

            return null;
    }

    return def;
}

function entities(exposes, list) {
    for (const e of exposes) {
        if (typeof e !== 'object' || e === null) {

            continue;
        }
        // specific types (light, switch, cover, lock, climate, fan): use their features
        if (Array.isArray(e.features) && !['composite', 'list'].includes(e.type)) {
            entities(e.features, list);

            continue;
        }
        const def = entity(e);
        if (def !== null && typeof list[def.property] !== 'object') {
            list[def.property] = def;
        }
    }

    return list;
}

let devices = {};
let added = [];
let changed = false;

for (const d of msg.payload) {
    if (typeof d !== 'object' || d === null || typeof d.ieee_address !== 'string' || d.type === 'Coordinator') {

        continue;
    }

    const id = d.ieee_address.replace(/^0x/i, '').toLowerCase();
    const old = previous[id] || {};
    const def = typeof d.definition === 'object' && d.definition !== null ? d.definition : {};
    const name = typeof d.friendly_name === 'string' ? d.friendly_name : id;

    let list = d.disabled === true ? {} : entities(Array.isArray(def.exposes) ? def.exposes : [], {});
    const values = { ...(old.values || {}), ...(states[name] || {}) };

    // entities not described by exposes, added when seen
    for (const k in Z.extra || {}) {
        if (Object.keys(list).length > 0 && typeof list[k] !== 'object' && (typeof (old.entities || {})[k] === 'object' || values[k] !== undefined)) {
            list[k] = Z.extra[k];
        }
    }

    devices[id] = {
        'id': id,
        'ieee': d.ieee_address,
        'name': name,
        'type': d.type || '',
        'model': def.model || d.model_id || '',
        'vendor': def.vendor || d.manufacturer || '',
        'description': def.description || '',
        'power': d.power_source || '',
        'firmware': d.software_build_id || '',
        'supported': d.supported !== false && typeof d.definition === 'object' && d.definition !== null,
        'disabled': d.disabled === true,
        'interview': d.interview_state || (d.interview_completed === true ? 'SUCCESSFUL' : (d.interviewing === true ? 'IN_PROGRESS' : 'PENDING')),
        'entities': list,
        'values': values,
        'availability': values.availability,
        'updated': Date.now()
    };

    const signature = JSON.stringify([name, devices[id].model, devices[id].firmware, list]);
    if (old.signature !== signature) {
        changed = true;
    }
    devices[id].signature = signature;

    if (typeof previous[id] !== 'object') {
        added.push(id);
    }

    node.send([{ 'topic': id, 'payload': id }, null, null, null, null]);
}

// keep the bridge pseudo device
if (typeof previous.bridge === 'object') {
    devices.bridge = previous.bridge;
}

// removed devices: clear retained DKNR and Home Assistant topics
for (const id in previous) {
    if (id === 'bridge' || typeof devices[id] === 'object') {

        continue;
    }
    changed = true;

    for (const k in previous[id].entities || {}) {
        const def = previous[id].entities[k];
        if (mqtt.topic) {
            node.send([null, null, { 'topic': [mqtt.topic, 'discovery', source, id, k].join('/'), 'payload': '', 'qos': 0, 'retain': true }, null, null]);
            node.send([null, null, { 'topic': [mqtt.topic, 'get', source, id, k].join('/'), 'payload': '', 'qos': 0, 'retain': true }, null, null]);
        }
        if (mqtt.homeassistant) {
            node.send([null, null, { 'topic': [mqtt.homeassistant, def.ha_type, source, id + '_' + k, 'config'].join('/'), 'payload': '', 'qos': 0, 'retain': true }, null, null]);
        }
    }
}

global.set('devices', devices, 'memoryOnly');

// first read of mains powered devices without known state
for (const id of added) {
    const dev = devices[id];
    if (dev.disabled || dev.interview !== 'SUCCESSFUL' || /battery/i.test(dev.power) || Object.keys(dev.values).some(k => !(k in (Z.extra || {}))) || !mqtt.source) {

        continue;
    }

    let get = {};
    for (const k in dev.entities) {
        if (dev.entities[k].access & 4) {
            get[k] = '';
        }
    }
    if (Object.keys(get).length > 0) {
        node.send([null, null, null, { 'topic': [mqtt.source, dev.name, 'get'].join('/'), 'payload': get, 'qos': 0, 'retain': false }, null]);
    }
}

node.status({ fill: 'green', shape: 'dot', text: (Object.keys(devices).length - (devices.bridge ? 1 : 0)) + ' appareil(s)' });

return [null, changed ? { 'topic': 'discovery', 'payload': '' } : null, null, null, { 'payload': 'devices' }];

// Zigbee2MQTT bridge/info and bridge/state, the bridge is published as a DKNR device (id: bridge)
// output 1: bridge device updated / output 2: discovery / output 3: UI refresh

const describe = global.get('describe', 'memoryOnly') || {};
const Z = describe.zigbee || {};
const devices = global.get('devices', 'memoryOnly') || {};
const info = global.get('bridge', 'memoryOnly') || {};
const kind = msg.topic.endsWith('bridge/info') ? 'info' : 'state';
let p = msg.payload;

if (Buffer.isBuffer(p)) {
    p = p.toString();
}
if (typeof p === 'string') {
    try {
        p = JSON.parse(p);
    } catch (e) {
        // Zigbee2MQTT 1.x legacy payload: online / offline
        p = { 'state': p.trim() };
    }
}
if (typeof p !== 'object' || p === null) {

    return;
}

if (kind === 'info') {
    info.version = p.version || '';
    info.coordinator = typeof p.coordinator === 'object' && p.coordinator !== null ? (p.coordinator.type || '') : '';
    info.channel = typeof p.network === 'object' && p.network !== null ? p.network.channel : undefined;
    info.pan_id = typeof p.network === 'object' && p.network !== null ? p.network.pan_id : undefined;
    info.permit_join = p.permit_join === true;
    // Zigbee2MQTT 2.x: permit_join_end (epoch ms), 1.x: permit_join_timeout (seconds)
    info.permit_join_end = p.permit_join_end || (typeof p.permit_join_timeout === 'number' ? Date.now() + p.permit_join_timeout * 1000 : undefined);
    if (!info.permit_join) {
        info.permit_join_end = undefined;
    }
} else {
    info.state = p.state === 'online' ? 'online' : 'offline';
}
info.updated = Date.now();

global.set('bridge', info, 'memoryOnly');

let added = false;
if (typeof devices.bridge !== 'object') {
    added = true;

    let entities = {};
    for (const k in Z.bridge || {}) {
        const b = Z.bridge[k];
        entities[k] = {
            'property': k,
            'name': b[0],
            'type': b[1],
            'access': b[2],
            'group': b[2] & 2 ? 'command' : 'sensor',
            'unit': '',
            'invert': false,
            'ha_type': b[3],
            'ha_device': b[4],
            'ha_state': '',
            'ha_category': b[5],
            'value_on': k === 'state' ? 'online' : true,
            'value_off': k === 'state' ? 'offline' : false,
            'display': ''
        };
    }

    devices.bridge = {
        'id': 'bridge',
        'ieee': '',
        'name': 'Zigbee2MQTT',
        'type': 'Bridge',
        'model': 'Zigbee2MQTT',
        'vendor': 'Koenkk',
        'description': 'Pont Zigbee2MQTT',
        'power': '',
        'firmware': '',
        'supported': true,
        'disabled': false,
        'interview': 'SUCCESSFUL',
        'entities': entities,
        'values': {},
        'updated': Date.now()
    };
}

const dev = devices.bridge;
if (info.state !== undefined) {
    dev.values.state = info.state;
}
if (info.version !== undefined) {
    dev.values.version = info.version;
    if (dev.firmware !== info.version) {
        dev.firmware = info.version;
        added = true;
    }
}
if (info.permit_join !== undefined) {
    dev.values.permit_join = info.permit_join;
}
dev.updated = Date.now();

global.set('devices', devices, 'memoryOnly');

node.status({ fill: info.state === 'online' ? 'green' : 'red', shape: 'dot', text: (info.state || '?') + (info.permit_join ? ' - appairage' : '') });

return [{ 'topic': 'bridge', 'payload': 'bridge' }, added ? { 'topic': 'discovery', 'payload': '' } : null, { 'payload': 'bridge' }];

// Zigbee2MQTT bridge/response to DKNR requests (transaction dknr-...)

let p = msg.payload;
if (Buffer.isBuffer(p)) {
    p = p.toString();
}
if (typeof p === 'string') {
    try {
        p = JSON.parse(p);
    } catch (e) {

        return;
    }
}
if (typeof p !== 'object' || p === null || typeof p.transaction !== 'string' || !p.transaction.startsWith('dknr-')) {

    return;
}

const data = typeof p.data === 'object' && p.data !== null ? p.data : {};

if (p.status !== 'ok') {
    node.status({ fill: 'red', shape: 'ring', text: msg.topic + ' : ' + (p.error || 'erreur') });

    return { 'payload': 'Zigbee2MQTT : ' + (p.error || 'erreur sur ' + msg.topic) };
}

node.status({ fill: 'green', shape: 'dot', text: msg.topic + ' : ok' });

switch (msg.topic) {
    case 'permit_join':

        return { 'payload': data.time > 0 ? 'Appairage autorisé pendant ' + data.time + ' secondes' : 'Appairage arrêté' };
    case 'device/rename':

        return { 'payload': 'Appareil renommé : ' + (data.to || '') };
    case 'device/remove':

        return { 'payload': 'Appareil supprimé : ' + (data.id || '') };
}

return;

// Zigbee2MQTT device state: base / friendly name = {property: value, ...}
// output 1: device updated (topic = device id) / output 2: discovery (new entity)

let p = msg.payload;
if (Buffer.isBuffer(p)) {
    p = p.toString();
}
if (typeof p === 'string') {
    try {
        p = JSON.parse(p);
    } catch (e) {

        return;
    }
}
if (typeof p !== 'object' || p === null || Array.isArray(p)) {

    return;
}

const name = msg.topic;
const states = global.get('states', 'memoryOnly') || {};
const devices = global.get('devices', 'memoryOnly') || {};

// last_seen can be ISO_8601, ISO_8601_local or epoch
if (typeof p.last_seen === 'number') {
    p.last_seen = new Date(p.last_seen).toISOString();
}

states[name] = { ...(states[name] || {}), ...p };
global.set('states', states, 'memoryOnly');

// device not known yet (or a group), it will get its state from bridge/devices
const id = Object.keys(devices).find(k => k !== 'bridge' && devices[k].name === name);
if (id === undefined) {

    return;
}

const dev = devices[id];
dev.values = { ...dev.values, ...p };
dev.updated = Date.now();

let added = false;
const extra = ((global.get('describe', 'memoryOnly') || {}).zigbee || {}).extra || {};
if (typeof p.last_seen === 'string' && typeof dev.entities.last_seen !== 'object' && Object.keys(dev.entities).length > 0 && extra.last_seen) {
    added = true;
    dev.entities.last_seen = extra.last_seen;
}

global.set('devices', devices, 'memoryOnly');

node.status({ fill: 'green', shape: 'dot', text: name + ' : ' + Object.keys(p).length });

return [{ 'topic': id, 'payload': id }, added ? { 'topic': 'discovery', 'payload': '' } : null];

// Zigbee2MQTT device availability: base / friendly name / availability = {"state": "online"} (or online / offline)
// output 1: device updated (topic = device id) / output 2: discovery (new entity) / output 3: UI refresh

let p = msg.payload;
if (Buffer.isBuffer(p)) {
    p = p.toString();
}
if (typeof p === 'string') {
    try {
        p = JSON.parse(p);
    } catch (e) {
        p = { 'state': p.trim() };
    }
}
if (typeof p !== 'object' || p === null || typeof p.state !== 'string') {

    return;
}

const state = p.state === 'online' ? 'online' : 'offline';

// keep it for a device not known yet
