// Publish changed values of a device to DKNR MQTT topic: topic / get / zigbee / id / entity

const enabled = global.get('mqtt.enabled', 'default') || false;
const topic = global.get('mqtt.topic', 'default') || '';
const describe = global.get('describe', 'memoryOnly') || {};
const devices = global.get('devices', 'memoryOnly') || {};
const transient = (describe.zigbee || {}).text || [];
const source = 'zigbee';
const id = msg.topic;
const dev = devices[id];

if (!enabled || topic === '' || typeof dev !== 'object') {

    return;
}

// Zigbee2MQTT value to DKNR value
function value(dev, def) {
    const raw = dev.values[def.property];
    if (raw === undefined || raw === null) {

        return undefined;
    }
    switch (def.type) {
        case 'binary':
            if (raw === def.value_on) {

                return 'ON';
            }
            if (raw === def.value_off) {

                return 'OFF';
            }

            return undefined;
        case 'number':
            if (typeof raw === 'number') {

                return raw;
            }

            return raw === '' || isNaN(Number(raw)) ? undefined : Number(raw);
        case 'enum':

            return String(raw);
        default:

            return typeof raw === 'object' ? JSON.stringify(raw) : String(raw);
    }
}

for (const k in dev.entities) {
    const def = dev.entities[k];
    const v = value(dev, def);
    if (v === undefined) {

        continue;
    }

    const last = 'last["' + id + '_' + k + '"]';
    if (flow.get(last, 'memoryOnly') === v) {

        continue;
    }
    flow.set(last, v, 'memoryOnly');

    node.send({
        'topic': [topic, 'get', source, id, k].join('/'),
        'payload': v,
        'qos': 0,
        'retain': !transient.includes(k)
    });
}

return;

