// input payload: {id, property, value}
// output 1: Zigbee2MQTT MQTT message / output 2: error notification

const mqtt = global.get('mqtt', 'default') || {};
const describe = global.get('describe', 'memoryOnly') || {};
const devices = global.get('devices', 'memoryOnly') || {};
const p = msg.payload || {};
const dev = devices[p.id];

function error(text) {
    node.status({ fill: 'red', shape: 'ring', text: text });

    return [null, { 'payload': text }];
}

if (typeof dev !== 'object') {

    return error('Appareil inconnu : ' + p.id);
}

const def = dev.entities[p.property];
if (typeof def !== 'object' || !(def.access & 2)) {

    return error(dev.name + ' : ' + p.property + ' non pilotable');
}

if (typeof mqtt.source !== 'string' || mqtt.source === '') {

    return error('Topic Zigbee2MQTT non configuré');
}

const raw = p.value === undefined || p.value === null ? '' : p.value;
const text = String(raw).trim();
let value;

switch (def.type) {
    case 'binary': {
        const v = text.toUpperCase();
        if (['ON', '1', 'TRUE'].includes(v) || raw === def.value_on) {
            value = def.value_on;
        } else if (['OFF', '0', 'FALSE'].includes(v) || raw === def.value_off) {
            value = def.value_off;
        } else if (v === 'TOGGLE') {
            value = def.value_toggle !== undefined ? def.value_toggle : (dev.values[p.property] === def.value_on ? def.value_off : def.value_on);
        }
        break;
    }
    case 'number': {
        const n = typeof raw === 'number' ? raw : Number(text.replace(',', '.'));
        if (text !== '' && !isNaN(n)) {
            value = n;
            if (typeof def.min === 'number' && value < def.min) {
                value = def.min;
            }
            if (typeof def.max === 'number' && value > def.max) {
                value = def.max;
            }
        }
        break;
    }
    case 'enum':
        value = (def.values || []).find(v => v.toLowerCase() === text.toLowerCase());
        break;
    default:
        value = text;
}

if (value === undefined) {

    return error(dev.name + ' : valeur ' + text + ' refusée pour ' + def.name);
}

node.status({ fill: 'blue', shape: 'dot', text: dev.name + ' - ' + p.property + ' - ' + value });

