if (p.id === 'bridge') {
    if (p.property === 'permit_join') {

        return [{
            'topic': [mqtt.source, 'bridge', 'request', 'permit_join'].join('/'),
            'payload': { 'time': value === true ? ((describe.zigbee || {}).permit || 254) : 0, 'transaction': 'dknr-' + Date.now() },
            'qos': 1,
            'retain': false
        }, null];
    }

    return error('Commande du pont inconnue');
}

let payload = {};
payload[p.property] = value;

return [{
    'topic': [mqtt.source, dev.name, 'set'].join('/'),
    'payload': payload,
    'qos': 1,
    'retain': false
}, null];

// Publish DKNR discovery and Home Assistant MQTT discovery of all known devices

const enabled = global.get('mqtt.enabled', 'default') || false;
const topic = global.get('mqtt.topic', 'default') || '';
const discovery = global.get('mqtt.homeassistant', 'default') || '';
