    return [null, { 'payload': 'Nom inchangé' }];
}

// Zigbee2MQTT topic rules
if (/[#+]/.test(name) || /\/$/.test(name) || /^\//.test(name) || /\/(set|get|availability)$/.test(name) || /\/\d+$/.test(name) || /^0x[0-9a-f]{16}$/i.test(name)) {

    return [null, { 'payload': 'Nom invalide : ' + name }];
}

if (Object.keys(devices).some(k => k !== id && devices[k].name === name)) {

    return [null, { 'payload': 'Ce nom est déjà utilisé' }];
}

return [{
    'topic': [mqtt.source, 'bridge', 'request', 'device', 'rename'].join('/'),
    'payload': { 'from': dev.ieee, 'to': name, 'homeassistant_rename': false, 'transaction': transaction },
    'qos': 1,
    'retain': false
}, null];
